parameters.jsCode:
// GitHub inputs
const repoInput = $input.first().json;

// Config variables — edit these!
const config = {
  repo: $env.REPO || repoInput.repo || 'owner/repo',
  githubToken: $env.GITHUB_TOKEN,
  claudeApiKey: $env.CLAUDE_API_KEY,
  destination: $env.DESTINATION || 'discord', // 'discord' or 'slack'
  webhookUrl: $env.WEBHOOK_URL,
  language: $env.LANGUAGE || 'EN', // EN or FR
};

// Calculate date range (last 7 days)
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = weekAgo.toISOString();

return {
  ...config,
  since,
  repo: config.repo,
  commitsUrl: `https://api.github.com/repos/${config.repo}/commits?since=${since}&per_page=100`,
  issuesUrl: `https://api.github.com/repos/${config.repo}/issues?state=closed&since=${since}&per_page=50`,
  pullsUrl: `https://api.github.com/repos/${config.repo}/pulls?state=closed&since=${since}&per_page=50`,
};

// Merge all three data streams
const items = $input.all();
const commits = items.find(i => i.json._node === 'Fetch Commits'.toLowerCase() || !i.json._node) || { json: [] };
const issues = items.find(i => i.json._node === 'Fetch Closed Issues') || { json: [] };
const pulls = items.find(i => i.json._node === 'Fetch Merged PRs') || { json: [] };

// Actually, n8n merges automatically. Let's just format the data.
const config = $('Build Config & URLs').first().json;

// Get commits from the first stream
const commitData = $('Fetch Commits').all();
const issueData = $('Fetch Closed Issues').all();
const pullData = $('Fetch Merged PRs').all();

// Format commits
const commitsFormatted = commitData.slice(0, 30).map(c => ({
  type: 'commit',
  author: c.commit?.author?.name || 'unknown',
  message: (c.commit?.message || '').split('\n')[0],
  date: c.commit?.author?.date?.split('T')[0],
  url: c.html_url
}));

// Format issues
const issuesFormatted = issueData.filter(i => i.pull_request === undefined).slice(0, 20).map(i => ({
  type: 'issue',
  title: i.title,
  number: i.number,
  state: 'closed',
  url: i.html_url
}));

// Format PRs
const pullsFormatted = pullData.slice(0, 20).map(p => ({
  type: 'pr',
  title: p.title,
  number: p.number,
  author: p.user?.login || 'unknown',
  url: p.html_url
}));

return {
  repo: config.repo,
  weekStart: config.since.split('T')[0],
  weekEnd: new Date().toISOString().split('T')[0],
  totalCommits: commitsFormatted.length,
  totalIssues: issuesFormatted.length,
  totalPRs: pullsFormatted.length,
  commits: commitsFormatted,
  issues: issuesFormatted,
  pulls: pullsFormatted,
  language: config.language
};

